def closestNode(n, edges, queries):
    # Build tree
    from collections import defaultdict, deque

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # Precompute parent and depth for LCA
    LOG = 15  # since n <= 10^4, log2(10^4) ~ 14
    parent = [[-1] * n for _ in range(LOG)]
    depth = [0] * n

    # Iterative DFS (avoids recursion limit on deep trees)
    stack = [(0, -1)]
    while stack:
        u, p = stack.pop()
        parent[0][u] = p
        for v in graph[u]:
            if v != p:
                depth[v] = depth[u] + 1
                stack.append((v, u))

    # Binary lifting table
    for k in range(1, LOG):
        for v in range(n):
            if parent[k-1][v] != -1:
                parent[k][v] = parent[k-1][parent[k-1][v]]

    # LCA query
    def lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u
        for k in reversed(range(LOG)):
            if parent[k][u] != -1 and depth[parent[k][u]] >= depth[v]:
                u = parent[k][u]
        if u == v:
            return u
        for k in reversed(range(LOG)):
            if parent[k][u] != -1 and parent[k][u] != parent[k][v]:
                u = parent[k][u]
                v = parent[k][v]
        return parent[0][u]

    # Path from u to v (inclusive)
    def path_nodes(u, v):
        l = lca(u, v)
        path = []
        # u to lca
        cur = u
        while cur != l:
            path.append(cur)
            cur = parent[0][cur]
        # lca to v
        stack = []
        cur = v
        while cur != l:
            stack.append(cur)
            cur = parent[0][cur]
        path.append(l)
        while stack:
            path.append(stack.pop())
        return path

    # Distance in tree
    def dist(u, v):
        l = lca(u, v)
        return depth[u] + depth[v] - 2 * depth[l]

    res = []
    for start, end, node in queries:
        pth = path_nodes(start, end)
        min_dist = float('inf')
        min_node = None
        for v in pth:
            d = dist(v, node)
            if d < min_dist or (d == min_dist and v < min_node):
                min_dist = d
                min_node = v
        res.append(min_node)
    return res
